pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 newVal) internal {
        bool reverted;
        try c.SetMinSum(newVal) { reverted = false; }
        catch { reverted = true; }
        assertTrue(!reverted && c.MinSum() == newVal);
    }

    function testFuzz_run(uint256 newVal) public {
        _run(newVal);
    }

    receive() external payable {}
}
